#!/usr/bin/env bash
# Bake plan 'bonifacio': 26 chunks x 7 styles = 182 jobs at z10 (1024 px, native z12)
# Estimate: 152 min GPU, 3.7 GB on the share
# all-sea chunks skipped: 23 ['10/535/379', '10/535/380', '10/535/381', '10/535/382', '10/536/382', '10/536/383', '10/539/380', '10/539/381', '10/539/382', '10/540/379', '10/540/380', '10/540/381', '10/540/382', '10/540/383', '10/540/384', '10/540/385', '10/541/379', '10/541/380', '10/541/381', '10/541/382', '10/541/383', '10/541/384', '10/541/385']
# land hexes at H3 res 5: 50 (room for 16 players at 3 each)
set -euo pipefail
: "${ATLAS_HOST:?}" "${ATLAS_MAPS:?}" "${ATLAS_MODELS:?}"

# 0. The image at argus-atlas 97f867e, the commit of the docs Atlas publishes (once per host):
#   git clone https://github.com/smk762/argus-atlas.git argus-atlas-97f867e && cd argus-atlas-97f867e && \
#   git checkout 97f867e303933c229c1c98a5bc549eb1c77eb1f0 && docker build -t argus-atlas:97f867e --build-arg EXTRAS="server,cli,tiles" .
docker image inspect argus-atlas:97f867e >/dev/null 2>&1 || { echo 'build argus-atlas:97f867e first (step 0)'; exit 1; }
# Chunks of another argus-atlas build here would be seamed against: re-bake into a fresh ATLAS_MAPS.
foreign=$(grep -L 97f867e303933c229c1c98a5bc549eb1c77eb1f0 "$ATLAS_MAPS"/areas/bonifacio/*/*/job.json 2>/dev/null || true)
[ -z "$foreign" ] || { echo "jobs from another argus-atlas build under $ATLAS_MAPS/areas/bonifacio/:"; echo "$foreign" | head -3; exit 1; }
RUN="docker run --rm -u $(id -u):$(id -g) -w /tmp --add-host host.docker.internal:host-gateway -e COMFYUI_BASE_URL=http://host.docker.internal:8188 -e ATLAS_ALLOW_BAKE=1 -e ATLAS_RECIPES_DIR=/data/recipes -e ATLAS_MODELS_DIR=/data/models -e ATLAS_JOBS_DIR=/data/out/atlas -v $ATLAS_HOST/dem:/data/dem -v $ATLAS_HOST/recipes:/data/recipes:ro -v $ATLAS_MODELS:/data/models:ro -v $ATLAS_MAPS:/data/out/atlas argus-atlas:97f867e"

# 1. DEM: Copernicus GLO-30 for the block plus margins, one GeoTIFF (all-sea tiles are filled with 0 m)
[ -f "$ATLAS_HOST"/dem/bonifacio_glo30.tif ] || \
  $RUN argus-atlas dem --bbox 8.0320,40.4035,9.8977,42.3361 --out /data/dem/bonifacio_glo30.tif --allow-missing

# 2. OSM for the whole block in one Overpass call, and its place names (a separate extract: never a control)
[ -f "$ATLAS_HOST"/dem/osm/bonifacio/osm.json ] || \
  $RUN argus-atlas osm --bbox 8.0420,40.4135,9.8877,42.3261 --zoom 12 --layers water,rivers,roads,forest,urban --out /data/dem/osm/bonifacio
[ -f "$ATLAS_HOST"/dem/osm/bonifacio-places/places.geojson ] || \
  $RUN argus-atlas osm --bbox 8.0420,40.4135,9.8877,42.3261 --zoom 12 --layers places --out /data/dem/osm/bonifacio-places

# 3. Recipes: a missing <style>.json is copied from antique.json with its name and preset swapped
test -f "$ATLAS_HOST"/recipes/antique.json || { echo "missing $ATLAS_HOST/recipes/antique.json"; exit 1; }
test -f "$ATLAS_HOST"/recipes/tolkien.json || sed 's/"antique"/"tolkien"/g' "$ATLAS_HOST"/recipes/antique.json > "$ATLAS_HOST"/recipes/tolkien.json
test -f "$ATLAS_HOST"/recipes/imhof.json || sed 's/"antique"/"imhof"/g' "$ATLAS_HOST"/recipes/antique.json > "$ATLAS_HOST"/recipes/imhof.json
test -f "$ATLAS_HOST"/recipes/watercolor.json || sed 's/"antique"/"watercolor"/g' "$ATLAS_HOST"/recipes/antique.json > "$ATLAS_HOST"/recipes/watercolor.json
test -f "$ATLAS_HOST"/recipes/cyberpunk.json || sed 's/"antique"/"cyberpunk"/g' "$ATLAS_HOST"/recipes/antique.json > "$ATLAS_HOST"/recipes/cyberpunk.json
test -f "$ATLAS_HOST"/recipes/minecraft.json || sed 's/"antique"/"minecraft"/g' "$ATLAS_HOST"/recipes/antique.json > "$ATLAS_HOST"/recipes/minecraft.json
test -f "$ATLAS_HOST"/recipes/pixel.json || sed 's/"antique"/"pixel"/g' "$ATLAS_HOST"/recipes/antique.json > "$ATLAS_HOST"/recipes/pixel.json

# 4. Chunks, one style at a time, north to south, west to east. A re-run skips chunks that have tiles.
curl -sf -m 5 http://127.0.0.1:8188/system_stats >/dev/null || { echo 'ComfyUI is not answering on :8188'; exit 1; }
mkdir -p "$ATLAS_MAPS"/areas/bonifacio/antique
[ -f "$ATLAS_MAPS"/areas/bonifacio/antique/antique-10-536-379/fantasy.pmtiles ] || \
  $RUN argus-atlas chunk --tile 10/536/379 --recipe antique --dem /data/dem/bonifacio_glo30.tif --size 1024 --margin 128 --sea-level 0 --layer water=/data/dem/osm/bonifacio/water.geojson --layer rivers=/data/dem/osm/bonifacio/rivers.geojson --layer roads=/data/dem/osm/bonifacio/roads.geojson --layer forest=/data/dem/osm/bonifacio/forest.geojson --layer urban=/data/dem/osm/bonifacio/urban.geojson --out /data/out/atlas/areas/bonifacio/antique/antique-10-536-379
[ -f "$ATLAS_MAPS"/areas/bonifacio/antique/antique-10-537-379/fantasy.pmtiles ] || \
  $RUN argus-atlas chunk --tile 10/537/379 --recipe antique --dem /data/dem/bonifacio_glo30.tif --size 1024 --margin 128 --sea-level 0 --layer water=/data/dem/osm/bonifacio/water.geojson --layer rivers=/data/dem/osm/bonifacio/rivers.geojson --layer roads=/data/dem/osm/bonifacio/roads.geojson --layer forest=/data/dem/osm/bonifacio/forest.geojson --layer urban=/data/dem/osm/bonifacio/urban.geojson --out /data/out/atlas/areas/bonifacio/antique/antique-10-537-379
